package com.bugtracker.service;

import com.bugtracker.dto.BugDtos.*;
import com.bugtracker.model.*;
import com.bugtracker.repository.BugRepository;
import com.bugtracker.repository.ProjectRepository;
import com.bugtracker.repository.SprintRepository;
import org.springframework.stereotype.Service;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.*;

@Service
public class BugService {
 private final BugRepository bugs; private final ProjectRepository projects; private final SprintRepository sprints; private final UserService users; private final HistoryService history; private final NotificationService notifications; private final EmailService email;
 public BugService(BugRepository bugs,ProjectRepository projects,SprintRepository sprints,UserService users,HistoryService history,NotificationService notifications,EmailService email){this.bugs=bugs;this.projects=projects;this.sprints=sprints;this.users=users;this.history=history;this.notifications=notifications;this.email=email;}
 public Bug find(Long id){return bugs.findById(id).orElseThrow(()->new RuntimeException("Bug not found"));}
 public List<Bug> all(){return bugs.findAllByOrderByUpdatedAtDesc();}
 public List<Bug> search(String q,BugStatus status,Priority priority,Severity severity,Long projectId,Long assigneeId){return all().stream().filter(b->q==null||q.isBlank()||((b.getTitle()+" "+Objects.toString(b.getDescription(),"")+" "+Objects.toString(b.getModule(),"")+" "+b.getProject().getName()).toLowerCase().contains(q.toLowerCase()))).filter(b->status==null||b.getStatus()==status).filter(b->priority==null||b.getPriority()==priority).filter(b->severity==null||b.getSeverity()==severity).filter(b->projectId==null||b.getProject().getId().equals(projectId)).filter(b->assigneeId==null||(b.getAssignee()!=null&&b.getAssignee().getId().equals(assigneeId))).toList();}
 public Bug create(CreateBugRequest r,User reporter){Project p=projects.findById(r.projectId()).orElseThrow(()->new RuntimeException("Project not found")); Bug b=Bug.builder().title(r.title()).description(r.description()).project(p).priority(r.priority()).severity(r.severity()).module(r.module()).stepsToReproduce(r.stepsToReproduce()).environment(r.environment()).category(r.category()).reporter(reporter).status(BugStatus.OPEN).dueDate(r.dueDate()).estimatedHours(r.estimatedHours()).slaDueAt(r.dueDate()!=null?r.dueDate():LocalDateTime.now().plusHours(slaHours(r.severity()))).build(); if(r.assigneeId()!=null){User assigned=users.find(r.assigneeId());if(!assigned.isActive()||assigned.getRole()!=Role.DEVELOPER)throw new IllegalArgumentException("Assignee must be an active developer");if(p.getMembers().stream().noneMatch(member->member.getId().equals(assigned.getId())))throw new IllegalArgumentException("Add the developer to this project before assigning an issue");b.setAssignee(assigned);} if(r.sprintId()!=null){Sprint sprint=sprints.findById(r.sprintId()).orElseThrow(()->new RuntimeException("Sprint not found"));if(!sprint.getProject().getId().equals(p.getId()))throw new IllegalArgumentException("Sprint must belong to the selected project");b.setSprint(sprint);} b=bugs.save(b); history.add(b,reporter,"BUG_CREATED","Bug created"); if(b.getAssignee()!=null){notifications.create(b.getAssignee(),"Bug assigned",b.getTitle(),"ASSIGN","/bugs/"+b.getId());email.send(b.getAssignee().getEmail(),"Bug assigned: "+b.getTitle(),"You have been assigned bug #"+b.getId());} return b;}
 public Bug status(Long id,BugStatus status,User actor){Bug b=find(id);BugStatus old=b.getStatus();if(!BugWorkflow.allows(old,status))throw new IllegalArgumentException("Invalid status transition: "+old+" to "+status);b.setStatus(status);b.setUpdatedAt(LocalDateTime.now());if(status==BugStatus.RESOLVED||status==BugStatus.CLOSED)b.setActualHours(b.getActualHours()!=null?b.getActualHours():hoursSince(b.getCreatedAt()));Bug saved=bugs.save(b);history.add(saved,actor,"STATUS_CHANGED",old+" → "+status);if(saved.getAssignee()!=null)notifications.create(saved.getAssignee(),"Bug status changed","#"+saved.getId()+" is now "+status,"STATUS","/bugs/"+saved.getId());return saved;}
 public Bug assign(Long id,Long assigneeId,User actor){Bug b=find(id);User u=assigneeId==null?null:users.find(assigneeId);if(u!=null&&(!u.isActive()||u.getRole()!=Role.DEVELOPER))throw new IllegalArgumentException("Assignee must be an active developer");if(u!=null&&b.getProject().getMembers().stream().noneMatch(member->member.getId().equals(u.getId())))throw new IllegalArgumentException("Add the developer to this project before assigning an issue");b.setAssignee(u);b.setUpdatedAt(LocalDateTime.now());Bug saved=bugs.save(b);history.add(saved,actor,"ASSIGNED",u==null?"Unassigned":"Assigned to "+u.getName());if(u!=null){notifications.create(u,"New bug assignment","#"+saved.getId()+" · "+saved.getTitle(),"ASSIGN","/bugs/"+saved.getId());email.send(u.getEmail(),"Bug assigned: "+saved.getTitle(),"You have been assigned bug #"+saved.getId());}return saved;}
 public Bug update(Long id,UpdateBugRequest r,User actor){Bug b=find(id);if(r.category()!=null)b.setCategory(r.category());if(r.actualHours()!=null)b.setActualHours(r.actualHours());if(r.dueDate()!=null){b.setDueDate(r.dueDate());b.setSlaDueAt(r.dueDate());}if(r.sprintId()!=null){Sprint sprint=sprints.findById(r.sprintId()).orElseThrow(()->new RuntimeException("Sprint not found"));if(!sprint.getProject().getId().equals(b.getProject().getId()))throw new IllegalArgumentException("Sprint must belong to the bug's project");b.setSprint(sprint);}b.setUpdatedAt(LocalDateTime.now());Bug saved=bugs.save(b);history.add(saved,actor,"BUG_UPDATED","Issue metadata updated");return saved;}
 public List<Bug> mine(User u){return bugs.findByReporterIdOrAssigneeIdOrderByUpdatedAtDesc(u.getId(),u.getId());}
 private long slaHours(Severity s){return switch(s){case BLOCKER,CRITICAL->4;case MAJOR->24;case MINOR->72;};}
 private double hoursSince(LocalDateTime t){return Math.round(Duration.between(t,LocalDateTime.now()).toMinutes()/60.0*10)/10.0;}
}
